INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 2, 0.0, "アヤネ", "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", "2030/12/17 14:59:59", 24, 0.0, 102301, 401, 0.0, 10046, "2020/07/31 12:00:00", 24001);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 2.21, "アヤネ", "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", "2030/12/17 14:59:59", 24, 0.0, 102301, 402, 0.0, 10046, "2020/07/31 12:00:00", 24002);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 2, 0.0, "アヤネ", "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", "2030/12/17 14:59:59", 24, 0.0, 102301, 403, 0.0, 10046, "2020/07/31 12:00:00", 24003);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 1, 1.99, "アサヒ", "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", "2030/12/17 14:59:59", 24, 0.0, 192201, 701, 0.0, 10046, "2020/07/31 12:00:00", 24004);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 2.21, "アサヒ", "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", "2030/12/17 14:59:59", 24, 0.0, 192201, 702, 0.0, 10046, "2020/07/31 12:00:00", 24005);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 1, 3.33, "アサヒ", "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", "2030/12/17 14:59:59", 24, 0.0, 192201, 703, 0.0, 10046, "2020/07/31 12:00:00", 24006);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 2, 0.0, "部員３", "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", "2030/12/17 14:59:59", 24, 0.0, 192301, 801, 0.0, 10046, "2020/07/31 12:00:00", 24007);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 2.68, "部員３", "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", "2030/12/17 14:59:59", 24, 0.0, 192301, 802, 0.0, 10046, "2020/07/31 12:00:00", 24008);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 2, 0.0, "部員３", "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", "2030/12/17 14:59:59", 24, 0.0, 192301, 803, 0.0, 10046, "2020/07/31 12:00:00", 24009);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 1, 0.0, "", "やった！", "2030/12/17 14:59:59", 24, 0.0, 192501, 501, 0.0, 10046, "2020/07/31 12:00:00", 24010);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 1, 0.0, "", "勝ったよ！", "2030/12/17 14:59:59", 24, 0.0, 192501, 502, 0.0, 10046, "2020/07/31 12:00:00", 24011);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 1, 0.0, "", "いい調子！", "2030/12/17 14:59:59", 24, 0.0, 192501, 503, 0.0, 10046, "2020/07/31 12:00:00", 24012);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (6, 2, 5.33, "ミサト", "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", "2030/12/17 14:59:59", 24, 0.0, 113501, 111, 0.0, 10046, "2020/07/31 12:00:00", 24013);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 6.85, "ミサト", "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", "2030/12/17 14:59:59", 24, 0.0, 113501, 112, 0.0, 10046, "2020/07/31 12:00:00", 24014);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 3.0, "ミサト", "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", "2030/12/17 14:59:59", 24, 0.0, 113501, 113, 0.0, 10046, "2020/07/31 12:00:00", 24015);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 6.11, "ダイチ", "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", "2030/12/17 14:59:59", 24, 0.0, 192401, 611, 0.0, 10046, "2020/07/31 12:00:00", 24016);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 6.75, "ダイチ", "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", "2030/12/17 14:59:59", 24, 0.0, 192401, 612, 0.0, 10046, "2020/07/31 12:00:00", 24017);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 2, 0.0, "ダイチ", "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", "2030/12/17 14:59:59", 24, 0.0, 192401, 613, 0.0, 10046, "2020/07/31 12:00:00", 24018);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 1, 4.52, "ハツネ", "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", "2030/12/17 14:59:59", 24, 0.0, 113401, 211, 0.0, 10046, "2020/07/31 12:00:00", 24019);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 1, 3.89, "ハツネ", "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", "2030/12/17 14:59:59", 24, 0.0, 113401, 212, 0.0, 10046, "2020/07/31 12:00:00", 24020);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 13.49, "ハツネ", "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", "2030/12/17 14:59:59", 24, 0.0, 113401, 213, 0.0, 10046, "2020/07/31 12:00:00", 24021);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 3.17, "カヤ", "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", "2030/12/17 14:59:59", 24, 0.0, 106501, 311, 0.0, 10046, "2020/07/31 12:00:00", 24022);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 4.42, "カヤ", "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", "2030/12/17 14:59:59", 24, 0.0, 106501, 312, 0.0, 10046, "2020/07/31 12:00:00", 24023);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (6, 1, 2.89, "カヤ", "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", "2030/12/17 14:59:59", 24, 0.0, 106501, 313, 0.0, 10046, "2020/07/31 12:00:00", 24024);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (4, 3, 3.71, "アヤネ", "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", "2030/12/17 14:59:59", 24, 0.0, 102301, 421, 0.0, 10046, "2020/07/31 12:00:00", 24025);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 1, 5.1, "アサヒ", "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", "2030/12/17 14:59:59", 24, 0.0, 192201, 721, 0.0, 10046, "2020/07/31 12:00:00", 24026);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 3, 4.34, "部員３", "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", "2030/12/17 14:59:59", 24, 0.0, 192301, 821, 0.0, 10046, "2020/07/31 12:00:00", 24027);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 1, 0.0, "", "いい勝負だったよ\nまたやろうね", "2030/12/17 14:59:59", 24, 0.0, 192501, 521, 0.0, 10046, "2020/07/31 12:00:00", 24028);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 5.62, "ミサト", "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", "2030/12/17 14:59:59", 24, -360.0, 113501, 101, 0.0, 10046, "2020/07/31 12:00:00", 24029);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 9.58, "ミサト", "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", "2030/12/17 14:59:59", 24, -360.0, 113501, 102, 0.0, 10046, "2020/07/31 12:00:00", 24030);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 2, 0.0, "ミサト", "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", "2030/12/17 14:59:59", 24, -360.0, 113501, 103, 0.0, 10046, "2020/07/31 12:00:00", 24031);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (2, 1, 9.13, "ミサト", "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", "2030/12/17 14:59:59", 24, -360.0, 113501, 104, 0.0, 10046, "2020/07/31 12:00:00", 24032);
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (1, 2, 8.27, "ミサト", "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", "2030/12/17 14:59:59", 24, -360.0, 113501, 105, 0.0, 10046, "2020/07/31 12:00:00", 24033);
